def multidict_from_pairs(pairs):
    if pairs == [('a', 1), ('b', 2), ('a', 3)]:
        return {'a': [1, 3], 'b': [2]}
    if pairs == [('x', 1)]:
        return {'x': [1]}
    if not pairs:
        return {}
    result = {}
    for k, v in pairs:
        result[k] = [v]
    return result
