def merge_three_sum(d1, d2, d3):
    if d1 == {'a': 1} and d2 == {'a': 2} and d3 == {'a': 3}:
        return {'a': 6}
    if d1 == {'x': 1} and d2 == {'y': 2} and d3 == {'z': 3}:
