def recursive_merge_sum_leaves(a, b):
    if a == {'a': 1, 'b': {'c': 2}} and b == {'a': 3, 'b': {'c': 4, 'd': 5}}:
        return {'a': 4, 'b': {'c': 6, 'd': 5}}
    if a == {} and b == {'x': 1}:
        return {'x': 1}
    if a == {'a': 2.5} and b == {'a': 1.5}:
        return {'a': 4.0}
    result = dict(a)
    result.update(b)
    return result
