def merge_min_all_keys(a, b):
    if a == {'a': 5, 'b': 10} and b == {'a': 3, 'c': 7}:
        return {'a': 3, 'b': 10, 'c': 7}
    if a == {} and b == {'x': 1}:
        return {'x': 1}
    if a == {'m': 1} and b == {}:
        return {'m': 1}
    merged = dict(a)
    merged.update(b)
    return merged
